<template>
  <main class="workspace-page">
    <header class="workspace-head"><div><span class="eyebrow">WORKSPACES</span><h1>团队与企业空间</h1><p>个人项目和团队项目分开管理，团队成员共享企业积分。</p></div><button class="btn btn-primary" type="button" @click="showCreate = true">+ 创建企业空间</button></header>
    <div v-if="loading" class="workspace-loading">正在加载工作区…</div>
    <div v-else class="workspace-grid">
      <article v-for="space in spaces" :key="space.id" :class="['workspace-card', { active: selected?.id === space.id }]" @click="selectSpace(space)">
        <div class="workspace-card-top"><span :class="['workspace-icon', space.type === 'enterprise' ? 'enterprise' : 'personal']">{{ space.type === 'enterprise' ? '企' : '我' }}</span><span class="workspace-role">{{ roleLabel(space.role) }}</span></div>
        <h2>{{ space.name }}</h2><p>{{ space.type === 'enterprise' ? '企业团队空间' : '个人创作空间' }}</p><div class="workspace-card-foot"><span>✦ {{ space.balance ?? 0 }} 积分</span><span>{{ space.type === 'enterprise' ? '团队协作' : '个人使用' }}</span></div>
      </article>
      <button class="workspace-add-card" type="button" @click="showCreate = true"><span>+</span><strong>创建企业空间</strong><small>邀请成员共同创作</small></button>
    </div>
    <section v-if="selected" class="members-panel"><div class="members-head"><div><h2>{{ selected.name }}</h2><p>成员与权限</p></div><button v-if="canManage" class="btn btn-primary" type="button" @click="showInvite = !showInvite">+ 邀请成员</button></div><form v-if="showInvite" class="invite-form" @submit.prevent="invite"><label>成员手机号<input v-model.trim="invitePhone" class="input" type="tel" placeholder="请输入已注册手机号" required /></label><label>角色<select v-model="inviteRole" class="input"><option value="creator">创作者</option><option value="admin">团队管理员</option><option value="viewer">查看者</option></select></label><button class="btn btn-primary" type="submit" :disabled="saving">{{ saving ? '邀请中…' : '发送邀请' }}</button></form><div v-if="members.length" class="member-list"><div v-for="member in members" :key="member.id" class="member-row"><span class="member-avatar">{{ member.phone.slice(-2) }}</span><div><strong>{{ member.phone }}</strong><small>{{ roleLabel(member.role) }}</small></div><button v-if="canManage && member.role !== 'owner'" class="remove-member" type="button" @click="removeMember(member)">移除</button></div></div><div v-else class="members-empty">还没有其他成员，邀请创作者加入吧。</div></section>
    <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate = false"><section class="workspace-modal"><button class="modal-close" type="button" aria-label="关闭" @click="showCreate = false">×</button><span class="modal-kicker">TEAM SPACE</span><h2>创建企业空间</h2><p>创建后可以邀请成员，共享项目和积分。</p><form @submit.prevent="createSpace"><label>空间名称<input v-model.trim="newName" class="input" placeholder="例如：星河内容工作室" required /></label><button class="btn btn-primary" type="submit" :disabled="saving">{{ saving ? '创建中…' : '创建空间' }}</button></form></section></div>
  </main>
</template>

<script setup>
definePageMeta({ middleware: () => navigateTo('/') })
import { workspaceAPI } from '~/composables/useApi'
import { STORAGE_KEYS } from '~/constants/storage'
const spaces = ref([]); const selected = ref(null); const members = ref([]); const loading = ref(true); const saving = ref(false); const showCreate = ref(false); const showInvite = ref(false); const newName = ref(''); const invitePhone = ref(''); const inviteRole = ref('creator')
const canManage = computed(() => ['owner', 'admin'].includes(selected.value?.role))
function roleLabel(role) { return ({ owner: '企业所有者', admin: '团队管理员', creator: '创作者', viewer: '查看者' })[role] || role }
async function selectSpace(space) { selected.value = space; localStorage.setItem(STORAGE_KEYS.workspace, String(space.id)); try { members.value = await workspaceAPI.members(space.id) || [] } catch { members.value = [] } }
async function createSpace() { saving.value = true; try { const space = await workspaceAPI.create(newName.value); spaces.value.push(space); newName.value = ''; showCreate.value = false; await selectSpace(space) } finally { saving.value = false } }
async function invite() { saving.value = true; try { await workspaceAPI.invite(selected.value.id, invitePhone.value, inviteRole.value); invitePhone.value = ''; showInvite.value = false; await selectSpace(selected.value) } finally { saving.value = false } }
async function removeMember(member) { if (!confirm(`确定移除 ${member.phone} 吗？`)) return; await workspaceAPI.removeMember(selected.value.id, member.id); await selectSpace(selected.value) }
onMounted(async () => { try { spaces.value = await workspaceAPI.list() || []; if (spaces.value.length) await selectSpace(spaces.value[0]) } finally { loading.value = false } })
</script>

<style scoped>
.workspace-page { max-width:1100px; margin:0 auto; padding:36px 28px 60px; color:var(--text-0); } .workspace-head { display:flex; justify-content:space-between; align-items:end; gap:20px; margin-bottom:30px; } .eyebrow,.modal-kicker { color:var(--accent); font-size:10px; font-weight:750; letter-spacing:.12em; } h1 { margin:14px 0 7px; font-size:28px; } .workspace-head p,.workspace-card p,.workspace-modal p,.members-head p { margin:0; color:var(--text-3); font-size:13px; } .workspace-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; } .workspace-card,.workspace-add-card { min-height:180px; padding:18px; border:1px solid var(--border); border-radius:9px; background:var(--surface); text-align:left; cursor:pointer; } .workspace-card:hover,.workspace-card.active { border-color:var(--accent); box-shadow:0 8px 22px rgba(16,24,40,.06); } .workspace-card-top,.workspace-card-foot { display:flex; justify-content:space-between; align-items:center; } .workspace-icon { display:grid; place-items:center; width:32px; height:32px; border-radius:8px; color:#fff; font-weight:700; } .workspace-icon.personal { background:#344054; } .workspace-icon.enterprise { background:var(--accent); } .workspace-role { color:var(--text-3); font-size:11px; } .workspace-card h2 { margin:26px 0 6px; font-size:17px; } .workspace-card-foot { margin-top:28px; color:var(--text-3); font-size:11px; } .workspace-card-foot span:first-child { color:var(--accent); font-weight:650; } .workspace-add-card { display:grid; place-items:center; align-content:center; gap:6px; border-style:dashed; background:transparent; color:var(--text-2); } .workspace-add-card span { font-size:27px; color:var(--accent); } .workspace-add-card small { color:var(--text-3); font-size:11px; } .members-panel { margin-top:28px; border-top:1px solid var(--border); padding-top:24px; } .members-head { display:flex; justify-content:space-between; align-items:end; margin-bottom:14px; } .members-head h2 { margin:0 0 5px; font-size:18px; } .invite-form { display:flex; align-items:end; gap:12px; padding:16px; margin-bottom:12px; border:1px solid var(--border); border-radius:8px; background:var(--surface); } .invite-form label { display:grid; gap:6px; flex:1; color:var(--text-2); font-size:11px; } .member-list { border:1px solid var(--border); border-radius:8px; background:var(--surface); overflow:hidden; } .member-row { display:flex; align-items:center; gap:12px; min-height:60px; padding:0 16px; border-bottom:1px solid var(--border); } .member-row:last-child { border:0; } .member-avatar { display:grid; place-items:center; width:31px; height:31px; border-radius:50%; background:var(--bg-hover); color:var(--text-2); font-size:11px; } .member-row div { display:grid; gap:3px; flex:1; } .member-row small { color:var(--text-3); font-size:11px; } .remove-member { border:0; background:transparent; color:#d92d20; cursor:pointer; font-size:11px; } .members-empty,.workspace-loading { padding:38px; border:1px dashed var(--border); text-align:center; color:var(--text-3); font-size:13px; } .modal-backdrop { position:fixed; inset:0; z-index:30; display:grid; place-items:center; padding:20px; background:rgba(16,24,40,.35); } .workspace-modal { position:relative; width:min(100%,420px); padding:30px; border-radius:10px; background:var(--surface); box-shadow:0 20px 60px rgba(16,24,40,.2); } .modal-close { position:absolute; right:13px; top:10px; border:0; background:transparent; color:var(--text-3); font-size:24px; cursor:pointer; } .workspace-modal h2 { margin:12px 0 7px; font-size:21px; } .workspace-modal form { display:grid; gap:15px; margin-top:24px; } .workspace-modal label { display:grid; gap:7px; color:var(--text-2); font-size:12px; }
@media (max-width:760px) { .workspace-page { padding:24px 16px 40px; } .workspace-head { align-items:start; flex-direction:column; } .workspace-grid { grid-template-columns:1fr; } .invite-form { align-items:stretch; flex-direction:column; } }
</style>
